#!/usr/bin/env node
// Vendors the kvnloo/ephemeral-ui card kit into Hermes Desktop as one offline HTML document.
//
//   node scripts/ephemeral-ui/build-kit.mjs <ephemeral-ui checkout> [--check]
//
// The document carries the kit's own card code (bundled with esbuild), its CSS, the public app and
// theme catalogs, and synthetic stand-ins for the trace and intent fixtures. The renderer inserts
// the card list between HEAD and TAIL and shows it in a sandboxed iframe. --check exits non-zero
// when the generated files are stale for the pinned revision.
//
// Ported from the T3 Code (experiments/openui-lab/ephemeral-ui) and Dash (app/scripts/ephemeral-kit)
// integrations of the same kit.
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { build, transform } from 'esbuild'

import { synthesize } from './synthetic.mjs'

export const KIT_REV = '63e06b29ffb0d7c5b9d482abebc0312335897321'

const here = dirname(fileURLToPath(import.meta.url))
const embeds = resolve(here, '../../src/components/assistant-ui/embeds')
const args = process.argv.slice(2)
const check = args.includes('--check')
const kit = resolve(args.find(arg => !arg.startsWith('--')) ?? '')

const git = (...rest) => execFileSync('git', ['-C', kit, ...rest], { encoding: 'utf8' }).trim()
const head = git('rev-parse', 'HEAD')
if (head !== KIT_REV) throw new Error(`ephemeral-ui checkout is at ${head}; this build pins ${KIT_REV}`)
const dirty = git('status', '--porcelain', '--', 'js', 'data', 'schema', '*.css')
if (dirty) throw new Error(`ephemeral-ui checkout has local edits:\n${dirty}`)

const read = path => readFileSync(join(kit, path), 'utf8')
const json = path => JSON.parse(read(path))

const script = (
  await build({
    entryPoints: [join(here, 'card-entry.js')],
    alias: { '@eui': join(kit, 'js') },
    bundle: true,
    format: 'iife',
    legalComments: 'none',
    logLevel: 'error',
    minify: true,
    target: 'es2020',
    write: false
  })
).outputFiles[0].text
const css = (
  await transform(['styles.css', 'trace.css', 'intent.css', 'infra.css'].map(read).join('\n'), {
    loader: 'css',
    minify: true
  })
).code

// App icons stay monograms, so the brand SVG paths are not shipped. The kit's trace and intent
// fixtures are sanitized real measurements; Hermes vendors synthetic values in their shape.
const apps = json('data/apps.json')
const data = {
  'data/apps.json': { ...apps, apps: apps.apps.map(app => ({ ...app, path: undefined })) },
  'data/themes.json': json('data/themes.json'),
  'data/trace-fixture.json': synthesize('trace', json('data/trace-fixture.json')),
  'data/intent-snapshot.json': synthesize('intent', json('data/intent-snapshot.json'))
}

const kinds = json('schema/card.v0.json').properties.kind.enum
const appsByKind = Object.fromEntries(
  kinds.map(kind => [kind, apps.apps.filter(app => (app.kinds ?? []).includes(kind)).map(app => app.id)])
)

// JSON: "<" only occurs inside strings, so \u003c is exact. Code and CSS must never close their element.
const safeJson = text => text.replaceAll('<', '\\u003c')
const safe = text => {
  if (/<\/(script|style)|<!--/i.test(text)) throw new Error('kit source would close its element')
  return text
}

const csp =
  "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; " +
  "font-src data:; media-src data: blob:; connect-src 'none'; frame-src 'none'; worker-src 'none'; " +
  "base-uri 'none'; form-action 'none'"
const hostCss =
  'html,body{margin:0;background:transparent}#eui-root{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,340px),1fr));align-items:start;gap:12px;padding:2px}' +
  '.eui-cell{min-width:0}.eui-cell>.eu-card{max-width:none;width:auto;margin:0}' +
  '.eui-fail{padding:10px 12px;border:1px solid var(--h-danger,#e5484d);border-radius:10px;color:var(--h-fg,#ddd);font:13px system-ui}'
const documentHead =
  '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
  `<meta http-equiv="Content-Security-Policy" content="${csp}">` +
  `<style>${safe(css)}${hostCss}</style>` +
  `<script type="application/json" id="eui-data">${safeJson(JSON.stringify(data))}</script><script>window.__EUI_CARDS=`
const documentTail = `</script></head><body><div id="eui-root"></div><script>${safe(script)}</script></body></html>`

const sha256 = createHash('sha256').update(documentHead + documentTail).digest('hex')
const banner =
  '// Generated by apps/desktop/scripts/ephemeral-ui/build-kit.mjs. Do not edit.\n' +
  `// Source: https://github.com/kvnloo/ephemeral-ui/tree/${KIT_REV}\n` +
  '/* eslint-disable */\n'
const files = {
  'ephemeral-ui-kinds.generated.ts':
    banner +
    `export const EPHEMERAL_UI_REVISION = ${JSON.stringify(KIT_REV)}\n` +
    `export const EPHEMERAL_UI_DOCUMENT_SHA256 = ${JSON.stringify(sha256)}\n` +
    `export const EPHEMERAL_UI_KINDS = ${JSON.stringify(kinds)} as const\n` +
    '/** Catalog apps that list each kind (data/apps.json); the first is the default. */\n' +
    `export const EPHEMERAL_UI_APPS_BY_KIND: Record<string, readonly string[]> = ${JSON.stringify(appsByKind)}\n`,
  'ephemeral-ui-kit.generated.ts':
    banner +
    `export const EPHEMERAL_UI_HEAD = ${JSON.stringify(documentHead)}\n` +
    `export const EPHEMERAL_UI_TAIL = ${JSON.stringify(documentTail)}\n`
}

let stale = []
for (const [name, text] of Object.entries(files)) {
  const path = join(embeds, name)
  if (check) {
    let current = ''
    try {
      current = readFileSync(path, 'utf8')
    } catch {
      // Missing output is stale output.
    }
    if (current !== text) stale.push(name)
  } else {
    writeFileSync(path, text)
  }
}

console.log(
  JSON.stringify({
    revision: KIT_REV,
    kinds: kinds.length,
    kib: (documentHead.length + documentTail.length) >> 10,
    sha256,
    ...(check ? { stale } : { wrote: Object.keys(files) })
  })
)
if (stale.length) process.exit(1)
